<?php
defined('ABSPATH') || exit;
final class SG_Income_Expense {
 private static function t(string $n):string{global $wpdb;return $wpdb->prefix.'sg_'.$n;}
 public static function init():void{add_action('rest_api_init',[__CLASS__,'routes']);}
 public static function routes():void{
  register_rest_route('sg/v1','/income-expenses',[
   ['methods'=>WP_REST_Server::READABLE,'callback'=>[__CLASS__,'listing'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('income_expense.view')],
   ['methods'=>WP_REST_Server::CREATABLE,'callback'=>[__CLASS__,'create'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('income_expense.create')]
  ]);
  register_rest_route('sg/v1','/income-expense-options',['methods'=>WP_REST_Server::READABLE,'callback'=>[__CLASS__,'options'],'permission_callback'=>static fn()=>is_user_logged_in()&&SG_Permissions::current_user_can('income_expense.view')]);
 }
 private static function date_ok(string $d):bool{$x=DateTime::createFromFormat('!Y-m-d',$d);return $x&&$x->format('Y-m-d')===$d;}
 private static function amount($v){$v=trim((string)$v);if(!preg_match('/^[0-9]{1,14}(\.[0-9]{1,2})?$/',$v)||(float)$v<=0)return false;$p=explode('.',$v,2);return(ltrim($p[0],'0')?:'0').'.'.str_pad($p[1]??'',2,'0');}
 public static function options():WP_REST_Response{global $wpdb;$c=$wpdb->get_results("SELECT id,category_type,category_name FROM ".self::t('categories')." WHERE is_active=1 AND category_type IN ('income','expense') ORDER BY category_type,category_name",ARRAY_A);$a=$wpdb->get_results("SELECT id,account_name,account_kind FROM ".self::t('cash_accounts')." WHERE status='active' ORDER BY account_kind,account_name",ARRAY_A);return new WP_REST_Response(['categories'=>$c?:[],'accounts'=>$a?:[]],200);}
 public static function listing(WP_REST_Request $r):WP_REST_Response{global $wpdb;$type=sanitize_key((string)$r->get_param('type'));$where='1=1';$args=[];if(in_array($type,['income','expense'],true)){$where.=' AND r.record_type=%s';$args[]=$type;}$sql="SELECT r.id,r.record_type,r.amount,r.record_date,r.document_no,r.description,c.category_name,a.account_name,j.entry_no FROM ".self::t('income_expenses')." r JOIN ".self::t('categories')." c ON c.id=r.category_id JOIN ".self::t('cash_accounts')." a ON a.id=r.cash_account_id JOIN ".self::t('journal_entries')." j ON j.id=r.journal_entry_id WHERE {$where} ORDER BY r.record_date DESC,r.id DESC LIMIT 300";$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);$tot=$wpdb->get_row("SELECT COALESCE(SUM(IF(record_type='income',amount,0)),0) income_total,COALESCE(SUM(IF(record_type='expense',amount,0)),0) expense_total FROM ".self::t('income_expenses'),ARRAY_A);return new WP_REST_Response(['items'=>$rows?:[],'totals'=>$tot],200);}
 private static function ledger(int $cid,string $type,string $name):int{global $wpdb;$code='IE-'.($type==='income'?'I-':'E-').str_pad((string)$cid,8,'0',STR_PAD_LEFT);$t=self::t('ledger_accounts');$id=(int)$wpdb->get_var($wpdb->prepare("SELECT id FROM {$t} WHERE account_code=%s",$code));if($id)return$id;$now=current_time('mysql',true);if(false===$wpdb->insert($t,['account_code'=>$code,'account_name'=>$name,'account_class'=>$type==='income'?'income':'expense','is_system'=>1,'is_active'=>1,'created_at'=>$now,'updated_at'=>$now]))throw new RuntimeException('Gelir/gider muhasebe hesabı oluşturulamadı.');return(int)$wpdb->insert_id;}
 public static function create(WP_REST_Request $r){global $wpdb;$type=sanitize_key((string)$r->get_param('record_type'));$cat=absint($r->get_param('category_id'));$cashid=absint($r->get_param('cash_account_id'));$amt=self::amount($r->get_param('amount'));$date=sanitize_text_field((string)$r->get_param('record_date'));$doc=sanitize_text_field((string)$r->get_param('document_no'));$desc=sanitize_textarea_field((string)$r->get_param('description'));$key=sanitize_text_field((string)$r->get_header('Idempotency-Key'));
  if(!in_array($type,['income','expense'],true)||!$cat||!$cashid||!$amt||!self::date_ok($date)||strlen($key)<16||strlen($key)>100)return new WP_Error('sg_ie_input','Gelir/gider bilgilerini kontrol edin.',['status'=>400]);
  $category=$wpdb->get_row($wpdb->prepare("SELECT id,category_name FROM ".self::t('categories')." WHERE id=%d AND category_type=%s AND is_active=1",$cat,$type),ARRAY_A);$cash=$wpdb->get_row($wpdb->prepare("SELECT id,ledger_account_id FROM ".self::t('cash_accounts')." WHERE id=%d AND status='active'",$cashid),ARRAY_A);if(!$category||!$cash)return new WP_Error('sg_ie_reference','Kategori veya kasa/banka hesabı bulunamadı.',['status'=>400]);
  $hash=hash('sha256',wp_json_encode([$type,$cat,$cashid,$amt,$date,$doc,$desc]));$idem=self::t('idempotency_keys');$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$idem} WHERE idempotency_key=%s",$key),ARRAY_A);if($old){if((int)$old['user_id']!==get_current_user_id()||!hash_equals($old['payload_hash'],$hash))return new WP_Error('sg_ie_conflict','İşlem anahtarı çakışması.',['status'=>409]);if($old['status']==='completed')return new WP_REST_Response(['message'=>'Kayıt daha önce oluşturuldu.','id'=>(int)$old['result_reference'],'duplicate'=>true],200);return new WP_Error('sg_ie_busy','İşlem kontrol ediliyor.',['status'=>409]);}
  $wpdb->query('START TRANSACTION');try{$now=current_time('mysql',true);if(false===$wpdb->insert($idem,['idempotency_key'=>$key,'operation'=>'income_expense.create','user_id'=>get_current_user_id(),'payload_hash'=>$hash,'status'=>'processing','created_at'=>$now]))throw new RuntimeException('Tekrarlı kayıt koruması oluşturulamadı.');$iid=(int)$wpdb->insert_id;$cl=self::ledger($cat,$type,$category['category_name']);$cashledger=(int)$cash['ledger_account_id'];$no='IG-'.wp_date('Ymd').'-'.strtoupper(wp_generate_password(8,false,false));$et=$type==='income'?'income':'expense';if(false===$wpdb->insert(self::t('journal_entries'),['entry_no'=>$no,'entry_date'=>$date,'entry_type'=>$et,'source_module'=>'income_expense','source_key'=>'income-expense:'.hash('sha256',$key),'document_no'=>$doc,'description'=>$desc,'status'=>'posted','created_by'=>get_current_user_id(),'posted_by'=>get_current_user_id(),'created_at'=>$now,'updated_at'=>$now,'posted_at'=>$now]))throw new RuntimeException('Muhasebe fişi oluşturulamadı.');$jid=(int)$wpdb->insert_id;
   $lines=$type==='income'?[['ledger_account_id'=>$cashledger,'cash_account_id'=>$cashid,'debit'=>$amt,'credit'=>'0.00'],['ledger_account_id'=>$cl,'debit'=>'0.00','credit'=>$amt]]:[['ledger_account_id'=>$cl,'debit'=>$amt,'credit'=>'0.00'],['ledger_account_id'=>$cashledger,'cash_account_id'=>$cashid,'debit'=>'0.00','credit'=>$amt]];foreach($lines as $i=>$line){$line=array_merge(['entry_id'=>$jid,'line_no'=>$i+1,'party_account_id'=>null,'cash_account_id'=>null,'description'=>$desc,'created_at'=>$now],$line);if(false===$wpdb->insert(self::t('journal_lines'),$line))throw new RuntimeException('Muhasebe fiş satırı kaydedilemedi.');}
   if(false===$wpdb->insert(self::t('cash_transactions'),['journal_entry_id'=>$jid,'cash_account_id'=>$cashid,'transaction_date'=>$date,'direction'=>$type==='income'?'in':'out','amount'=>$amt,'document_no'=>$doc,'description'=>$desc?:$category['category_name'],'created_by'=>get_current_user_id(),'created_at'=>$now]))throw new RuntimeException('Kasa/banka hareketi kaydedilemedi.');if(false===$wpdb->insert(self::t('income_expenses'),['record_type'=>$type,'category_id'=>$cat,'cash_account_id'=>$cashid,'journal_entry_id'=>$jid,'amount'=>$amt,'record_date'=>$date,'document_no'=>$doc,'description'=>$desc,'created_by'=>get_current_user_id(),'created_at'=>$now]))throw new RuntimeException('Gelir/gider kaydı oluşturulamadı.');$rid=(int)$wpdb->insert_id;if(false===$wpdb->update($idem,['result_reference'=>(string)$rid,'status'=>'completed','completed_at'=>$now],['id'=>$iid]))throw new RuntimeException('İşlem durumu güncellenemedi.');$wpdb->insert(self::t('audit_logs'),['user_id'=>get_current_user_id(),'event_key'=>'income_expense.posted','object_type'=>'income_expense','object_id'=>$rid,'request_id'=>$key,'details'=>wp_json_encode(['type'=>$type,'amount'=>$amt,'cash_account_id'=>$cashid,'journal_entry_id'=>$jid]),'created_at'=>$now]);$wpdb->query('COMMIT');return new WP_REST_Response(['message'=>($type==='income'?'Gelir':'Gider').' kaydedildi; kasa/banka hareketi otomatik oluşturuldu.','id'=>$rid],201);
  }catch(Throwable $e){$wpdb->query('ROLLBACK');return new WP_Error('sg_ie_save',$e->getMessage(),['status'=>500]);}}
}
